gq 3;
query titled() {
  match { $d: Doc  $d.title contains "graph"  $d.title starts_with "The" }
  return { $d.title }
}

gq 3;
query tagged() {
  match { $d: Doc  $d.tags contains "rust" }
  return { $d.title }
}

gq 3;
query mentions($s: String, $q: String) {
  match { $d: Doc  search($d.body, $s)  fuzzy($d.body, $q, 2) }
  return { $d.title }
}

gq 3;
query similar($q: Vector(3)) {
  match { $d: Doc  $d.year >= 2025 }
  return { $d.title }
  order { nearest($d.embedding, $q) }
  limit 20
}

gq 3;
query about($q: String) {
  match { $d: Doc }
  return { $d.title, bm25($d.body, $q) as s }
  order { bm25($d.body, $q) desc }
  limit 10
}

gq 3;
query retire($h: String) {
  delete WorksAt where @src = $h
}

gq 3;
query birthday($h: String) {
  update Person set { age: age + 1 } where handle = $h
}

gq 3;
query big_employers($min: I64) {
  match { $c: Company  $p worksAt $c }
  return { $c.name, count($p) as n }
  having { n >= $min }
  order { n desc }
}

gq 3;
query people_and_employers() {
  match { $p: Person  optional $p worksAt $c }
  return { $p.name, $c.name }
}

gq 3;
query with_city() {
  match { $p: Person }
  return { $p.name, coalesce($p.city, "unknown") as city, CASE WHEN $p.age >= 65 THEN "senior" ELSE "active" END as band }
}

gq 3;
query doubled($min: I32) {
  match { $p: Person  $p.age * 2 >= $min }
  return { $p.name, $p.age * 2 as twice, 2026 -$p.age as born_about }
}

gq 3;
query adults($min: I32) {
  match { $p: Person { age >= $min } }
  return { $p.name }
  order { $p.age desc }
}

gq 3;
query person {
  match { $p: Person { handle: $h } }
  return { $p.name, $p.city }
}

gq 3;
mutation hire($h: String, $slug: String) {
  insert Person { handle: $h, name: $h }
  insert WorksAt { from: $h, to: $slug }
}

gq 3;
query birthday($h: String) {
  match { $p: Person { handle: $h } }
  update $p set { age: $p.age + 1 }
}

gq 3;
query in_collection($slug: String) {
  match { $x: Collection { slug: $slug }  $d in $x }
  return { $d.title }
}

gq 3;
query well_connected($min: I64) {
  match { $p: Person  where count { $p knows $q } >= $min }
  return { $p.name }
}

gq 3;
query around($h: String) {
  match { $p: Person { handle: $h }  $p -knows- $f }
  return { $f.name }
}

gq 3;
query latest_per_author() {
  match {
    $p: Person
    let $d in { match { $p authored $d } return { $d } order { $d.year desc } limit 3 }
  }
  return { $p.name, $d.title, $d.year }
}

gq 3;
query distinct_cities() {
  match { $p: Person }
  return { count(*) as cities }
}

gq 3;
query homeless() {
  match { $p: Person  $p.city = null }
  return { $p.name }
}

gq 3;
query adults($min: I32) {
  match { $p: Person  $p.age >= $min }
  return { $p.name }
  order { $p.age DESC }
}

gq 3;
query average_headcount() {
  match { $c: Company  $p worksAt $c }
  return { avg(count($p)) as mean, max(count($p)) as largest }
}

gq 3;
query weighted($q: String, $v: Vector(3)) {
  match {
    from distance({ match { $d: Doc } return { $d } }, $d.embedding, $v)
    from bm25({ match { $d: Doc } return { $d } }, $d.body, $q)
  }
  return { $d.title, 0.7 * (1.0 / (1.0 + $distance)) + 0.3 * $score as s }
  order { s desc }
  limit 10
}

gq 3;
query similar($q: Vector(3)) {
  match { from nearest({ match { $d: Doc  $d.year >= 2025 } return { $d } }, $d.embedding, $q) }
  return { $d.title }
  order { $distance }
  limit 20
}

gq 3;
query people_and_companies() {
  match { $p: Person } return { $p.name as name, "person" as kind }
  union
  match { $c: Company } return { $c.name as name, "company" as kind }
}

gq 3;
query in_cities() {
  match { $p: Person  $p.city == 'Berlin' or $p.city == 'Paris' }
  return { $p.name }
}

gq 3;
query colleagues($of: String) {
  match { $p: Person { handle: $of }  $p worksAt $c  $q worksAt $c  $q != $p }
  return { $q }
}

query colleagues_of_colleagues($of: String) {
  match {
    from { match { from colleagues ($of) } return { $q as c } }
    from { match { from colleagues ($c.handle) } return { $q as r } }
  }
  return distinct { $r.name }
}
